import type { DbSchema } from '../dbschema/model';
import { validateDbSchema } from '../dbschema/model';

const esc = (s: string): string => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const known = (n: number): boolean => [1, 2, 3, 4, 6, 7].includes(n);
const button = (action: string, label: string, attrs = ''): string => `<button type="button" data-action="${action}" ${attrs}>${label}</button>`;
/** Fragments are generated by the host, never from untrusted webview HTML. */
export function renderErdEditState(schema: DbSchema, options: { hint?: string; message?: string } = {}): { diagram: string; feedback: string; canSave: boolean } {
 const validation = validateDbSchema(schema);
 const width = 350, gap = 40, cols = Math.max(1, Math.ceil(Math.sqrt(schema.tables.length)));
 let y = 0;
 const cards: string[] = [];
 for (let start = 0; start < schema.tables.length; start += cols) {
  const row = schema.tables.slice(start, start + cols);
  let rowHeight = 0;
  row.forEach((table, col) => {
   const height = 175 + table.fields.length * 115;
   rowHeight = Math.max(rowHeight, height);
   const fields = table.fields.map((field, index) => {
    if (!known(field.typeCode)) return `<div class="raw">${esc(field.name)} — raw type ${field.typeCode}, size ${field.size}</div>`;
    const options = [1,2,3,4,6,7].map(n => `<option value="${n}"${n === field.typeCode ? ' selected' : ''}>${n}</option>`).join('');
    return `<div class="field" data-field="${index}"><label>Name <input data-value="name" value="${esc(field.name)}"></label><label>Type <select data-value="typeCode">${options}</select></label><label>Size <input data-value="size" value="${field.size}"></label>${button('updateField','Apply column')}${button('moveUp','↑', index === 0 || !known(table.fields[index - 1].typeCode) ? 'disabled' : '')}${button('moveDown','↓', index === table.fields.length - 1 || !known(table.fields[index + 1].typeCode) ? 'disabled' : '')}${button('deleteField','Delete column')}</div>`;
   }).join('');
   cards.push(`<foreignObject class="edit-card" x="${col * (width + gap)}" y="${y}" width="${width}" height="${height}"><div xmlns="http://www.w3.org/1999/xhtml" class="edit-body" data-table="${table.index}"><strong>Table #${table.index}</strong><label>Name <input data-table-value="name" value="${esc(table.name)}"></label><label>Max records <input data-table-value="maxRecords" value="${table.maxRecords}"></label>${button('updateTable','Apply table')}${button('deleteTable','Delete table')}${fields}${button('addField','Add column')}</div></foreignObject>`);
  });
  y += rowHeight + gap;
 }
 const feedback = `<section aria-live="polite">${options.message ? `<p>${esc(options.message)}</p>` : ''}<ul>${validation.errors.map(e => `<li class="error">${esc(e)}</li>`).join('')}${validation.warnings.map(w => `<li class="warning">${esc(w)}</li>`).join('')}</ul>${options.hint !== undefined ? `<h2>main.iri hint</h2><p>Renamed or deleted fields can break existing code and dbaccess routines. Regenerate main.iri in Revolution.</p><pre>${esc(options.hint)}</pre>` : ''}</section>`;
 return { diagram: cards.join(''), feedback, canSave: validation.errors.length === 0 };
}
